  if(bottomTab==='Variables'){content.innerHTML=`<div class="variable-table">${Object.entries(project.variables).map(([name,value])=>`<label><span>${escape(name)}</span><input type="number" data-variable="${escape(name)}" aria-label="Variable ${escape(name)}" value="${value}"></label>`).join('')}</div><button id="add-variable">＋ Add variable</button>`;content.querySelectorAll('[data-variable]').forEach(input=>input.onchange=()=>{if(playing)return;const v=+input.value;if(!Number.isFinite(v))return;record();project.variables[input.dataset.variable]=v;changed()});$('#add-variable').onclick=()=>{if(playing)return;const name=prompt('Variable name (letters, numbers and underscores)');if(!name)return;if(!/^[a-zA-Z][a-zA-Z0-9_]{0,39}$/.test(name)){notify('Use 1–40 letters, numbers or underscores.');return}if(Object.hasOwn(project.variables,name)){notify('That variable already exists.');return}record();project.variables[name]=0;changed()}}
  if(bottomTab==='Input Mapper')renderInputs(content);if(bottomTab==='Console')content.innerHTML=consoleRows();if(bottomTab==='Debug')renderDebug(content);
