 function diagnostics(){const issues=[];if(!project.objects.some(o=>o.type==='player'))issues.push({message:'No player in this scene.',evidence:'Scene contains no Player object.',fix:'Add a player to make the scene playable.',type:'player'});for(const o of project.objects){if(o.type==='coin'&&!o.events?.some(e=>e.action==='score'))issues.push({message:`${o.name} has no collection event.`,evidence:`Coin at (${o.x}, ${o.y}) has no On Touch → Score action.`,fix:'Add On Touch (Player) → Add 1 to Score.',object:o.id,type:'coin'})}return issues}
 function renderDebug(el){const issues=diagnostics();el.innerHTML=`<div class="debug-heading">${icon('bolt',15)} Project checks <span>Local checks · no AI required</span><label class="orbit-footer">Orbit <input id="orbit-debug-toggle" type="checkbox" aria-label="Enable Orbit" ${orbitEnabled()?'checked':''}></label></div>${issues.length?issues.map((issue,i)=>`<div class="diagnostic"><b>⚠ ${escape(issue.message)}</b><p><strong>Evidence:</strong> ${escape(issue.evidence)}</p><p><strong>Proposed fix:</strong> ${escape(issue.fix)}</p><button data-fix="${i}" class="purple-button">Review fix</button></div>`).join(''):'<div class="debug-clear">✓ No issues detected by current project checks.</div>'}`;el.querySelectorAll('[data-fix]').forEach(b=>b.onclick=()=>reviewFix(issues[+b.dataset.fix]));const toggle=el.querySelector('#orbit-debug-toggle');if(toggle)toggle.onchange=e=>{try{const prefs=JSON.parse(localStorage.getItem('playform.preferences')||'{}');prefs.ai=e.target.checked;localStorage.setItem('playform.preferences',JSON.stringify(prefs));document.querySelector('#ai').checked=prefs.ai;renderWorkspace();renderConsole()}catch{notify('Could not save Orbit preference.')}};renderOrbit(el)}
 function orbitEnabled(){try{return !!JSON.parse(localStorage.getItem('playform.preferences')||'{}').ai}catch{return false}}
 function renderOrbit(el){if(!orbitEnabled())return;const section=document.createElement('section');section.className='orbit-assist';section.innerHTML=`<strong>✧ Orbit</strong><p>Your game-making companion. Local guidance works without a model.</p>${project.description?`<p><b>Game brief:</b> ${escape(project.description)}</p>`:''}<div class="orbit-quick"><button data-guide="score">Make a collectible</button><button data-guide="gravity">Change gravity</button><button data-guide="layout">Change layout</button></div><div id="orbit-guidance"></div><form id="orbit-form"><label>Ask your connected AI model<input id="orbit-question" required maxlength="2000" placeholder="Why doesn’t my coin collect?"></label><button class="purple-button" id="ask-orbit" type="submit">Ask Orbit</button></form><p class="orbit-model-note">Desktop includes a local model. Website AI needs a connected model server.</p><div id="orbit-answer" aria-live="polite"></div>`;el.append(section);section.querySelectorAll('[data-guide]').forEach(b=>b.onclick=()=>{$('#orbit-guidance').textContent={score:'Select a coin → Quick Behavior Builder → On Touch (Player) → Add to Score and collect → Add event. Test with F5.',gravity:'Open World physics from Tools or the Project panel. Choose Earth, Moon, Mars, Zero Gravity, or a custom multiplier. Earth is 1.0×.',layout:'Open View → Customize layout. Move panels between docks, resize with dividers, or choose a preset. Your choices save on this device.'}[b.dataset.guide]});$('#orbit-form').onsubmit=async e=>{e.preventDefault();const answer=$('#orbit-answer'),button=$('#ask-orbit'),question=$('#orbit-question').value;button.disabled=true;answer.textContent='Orbit is checking the project…';try{const response=await fetch('/api/orbit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question,project:{name:project.name,description:project.description||'',template:project.template,gravity:project.gravity,objects:project.objects.slice(0,40).map(o=>({name:o.name,type:o.type,x:o.x,y:o.y,events:o.events||[]})),issues:diagnostics()}})});const result=await response.json();if(!response.ok)throw Error(result.error||'Orbit could not connect.');answer.innerHTML=`<p><b>Suspected cause / goal:</b> ${escape(result.answer.suspectedCause)}</p><p><b>Evidence:</b> ${escape(result.answer.evidence)}</p><p><b>Proposed fix:</b> ${escape(result.answer.proposedFix)}</p><small>Advice only. Orbit has not changed your project.</small>`}catch(error){answer.textContent=error.message}finally{button.disabled=false}}}
 function reviewFix(issue){showDialog('Review project change',`<p><b>Suspected cause:</b> ${escape(issue.message)}</p><p><b>Evidence:</b> ${escape(issue.evidence)}</p><p><b>Proposed fix:</b> ${escape(issue.fix)}</p><button id="approve-fix" class="purple-button">Approve & apply fix</button>`);$('#approve-fix').onclick=()=>{if(playing){notify('Stop the game before applying a fix.');return}if(issue.type==='player')addObject('player');else{const o=project.objects.find(o=>o.id===issue.object);if(o){record();o.events??=[];o.events.push({id:crypto.randomUUID(),condition:'touch',action:'score',value:1});selected=o.id;changed();addLog(`Approved collection event added to ${o.name}.`,'success')}}$('.editor-dialog').close()}}
