 function updateCounts(){if(!$('#object-count'))return;$('#object-count').textContent=`Objects: ${project.objects.length}`;$('#event-count').textContent=`Events: ${project.objects.reduce((sum,o)=>sum+(o.events?.length||0),0)}`}
 function physicsDialog(){showDialog('World physics',`<p class="muted">Gravity is relative to Earth = 1.0×. Changes apply to the game preview.</p><label>Gravity preset<select id="physics-preset">${gravities.map(([n,g])=>`<option value="${g}" ${g===project.gravity?'selected':''}>${n}</option>`).join('')}<option value="custom">Custom</option></select></label><label>Gravity multiplier<input id="gravity-input" type="number" min="0" max="10" step="0.01" value="${project.gravity}"></label><button id="save-physics" class="purple-button">Apply physics</button>`);$('#physics-preset').onchange=e=>{if(e.target.value!=='custom')$('#gravity-input').value=e.target.value};$('#save-physics').onclick=()=>{const v=+$('#gravity-input').value;if(!Number.isFinite(v)||v<0||v>10){notify('Choose a gravity between 0 and 10×.');return}if(playing){notify('Stop the game before changing physics.');return}record();project.gravity=v;$('.editor-dialog').close();changed()}}
 function renderInputs(content){project.inputs??={left:'ArrowLeft',right:'ArrowRight',up:'ArrowUp',down:'ArrowDown',jump:'Space',shoot:'Space'};project.controller??={jump:0,shoot:1};content.innerHTML=`<div class="input-mapper">${Object.entries(project.inputs).map(([action,key])=>`<label><span>${escape(action[0].toUpperCase()+action.slice(1))}</span><input data-input-action="${action}" aria-label="Binding ${action}" value="${escape(key)}" readonly><select data-mouse-action="${action}" aria-label="Mouse binding ${action}"><option value="">Mouse…</option><option value="Mouse0">Left click</option><option value="Mouse2">Right click</option></select></label>`).join('')}<label><span>Controller jump</span><select data-controller="jump">${Array.from({length:16},(_,i)=>`<option value="${i}" ${project.controller.jump===i?'selected':''}>Button ${i}</option>`).join('')}</select></label><label><span>Controller shoot</span><select data-controller="shoot">${Array.from({length:16},(_,i)=>`<option value="${i}" ${project.controller.shoot===i?'selected':''}>Button ${i}</option>`).join('')}</select></label><button id="reset-inputs">Reset bindings</button></div>`;content.querySelectorAll('[data-input-action]').forEach(input=>{input.onfocus=()=>input.value='Press a key…';input.onblur=()=>input.value=project.inputs[input.dataset.inputAction];input.onkeydown=e=>{e.preventDefault();e.stopPropagation();if(playing)return;record();project.inputs[input.dataset.inputAction]=e.code;input.value=e.code;input.blur();persist()}});content.querySelectorAll('[data-mouse-action]').forEach(select=>select.onchange=()=>{if(!select.value||playing)return;record();project.inputs[select.dataset.mouseAction]=select.value;persist();renderWorkspace()});content.querySelectorAll('[data-controller]').forEach(select=>select.onchange=()=>{if(playing)return;record();project.controller[select.dataset.controller]=+select.value;persist()});$('#reset-inputs').onclick=()=>{if(playing)return;record();project.inputs={left:'ArrowLeft',right:'ArrowRight',up:'ArrowUp',down:'ArrowDown',jump:'Space',shoot:'Space'};project.controller={jump:0,shoot:1};persist();renderWorkspace()}}
