 function inputPressed(action){const defaults={left:'ArrowLeft',right:'ArrowRight',up:'ArrowUp',down:'ArrowDown',jump:'Space',shoot:'Space'},aliases={left:'KeyA',right:'KeyD',up:'KeyW',down:'KeyS',jump:'ArrowUp'};if(keyState.has(project.inputs?.[action]||defaults[action])||!project.inputs&&keyState.has(aliases[action]))return true;const pad=navigator.getGamepads?.()?.[0];if(!pad)return false;return action==='left'?pad.axes[0]<-.3||pad.buttons[14]?.pressed:action==='right'?pad.axes[0]>.3||pad.buttons[15]?.pressed:action==='up'?pad.axes[1]<-.3||pad.buttons[12]?.pressed:action==='down'?pad.axes[1]>.3||pad.buttons[13]?.pressed:pad.buttons[project.controller?.[action]??(action==='jump'?0:1)]?.pressed}
 function editAudio(){if(playing){notify('Stop the game before editing audio.');return}openSoundEditor({project,notify,onChange:change=>{record();if(change.remove){project.sounds=project.sounds.filter(s=>s.id!==change.remove);for(const o of project.objects)o.events=(o.events||[]).filter(e=>e.soundId!==change.remove)}else{const index=project.sounds.findIndex(s=>s.id===change.sound.id);if(index>=0)project.sounds[index]=change.sound;else project.sounds.push(change.sound)}changed();renderAssets()}})}
 function gameSize(){showDialog('Game size',`<div class="size-presets">${[['Desktop',1280,720],['HD',1920,1080],['Phone portrait',390,844],['Phone landscape',844,390],['Square',800,800],['Classic',960,540]].map(([name,w,h])=>`<button data-resolution="${w},${h}">${name}</button>`).join('')}</div><form id="game-size-form"><div class="game-size-grid"><label>Width (px)<input id="game-width" type="number" required min="160" max="4096" value="${project.width}"></label><label>Height (px)<input id="game-height" type="number" required min="160" max="4096" value="${project.height}"></label></div><label class="check"><input id="scale-scene" type="checkbox" checked>Scale existing objects to fit</label><button type="submit" class="purple-button">Apply size</button></form>`);$$('[data-resolution]').forEach(b=>b.onclick=()=>{const[w,h]=b.dataset.resolution.split(',');$('#game-width').value=w;$('#game-height').value=h});$('#game-size-form').onsubmit=e=>{e.preventDefault();if(playing){notify('Stop the game before resizing.');return}const w=+$('#game-width').value,h=+$('#game-height').value;if(![w,h].every(v=>Number.isInteger(v)&&v>=160&&v<=4096))return;record();if($('#scale-scene').checked)for(const o of project.objects){o.x=Math.round(o.x*w/project.width);o.y=Math.round(o.y*h/project.height);o.w=Math.max(1,Math.round(o.w*w/project.width));o.h=Math.max(1,Math.round(o.h*h/project.height))}project.width=w;project.height=h;zoom=1;pan={x:0,y:0};$('.editor-dialog').close();changed()}}
