 function bindActions(el){el.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{const action=b.dataset.action;$$('.editor-menu').forEach(d=>d.open=false);if(b.closest('.editor-dialog')&&action!==undefined)$('.editor-dialog').close();actions[action]?.();if(action==='mobile-menu')bindActions($('.editor-dialog'))})}
