 function viewTransform(){const camera=playing?runtime.objects.find(o=>o.type==='camera'):null;if(camera){const r=$('canvas').getBoundingClientRect(),scale=Math.min(r.width/camera.w,r.height/camera.h)*zoom;return{scale,x:(r.width-camera.w*scale)/2-camera.x*scale+pan.x,y:(r.height-camera.h*scale)/2-camera.y*scale+pan.y,r}}const r=$('canvas').getBoundingClientRect(),scale=Math.min(r.width/project.width,r.height/project.height)*zoom;return{scale,x:(r.width-project.width*scale)/2+pan.x,y:(r.height-project.height*scale)/2+pan.y,r}}
