 function setupLayout(){for(const panel of Object.values(panels)){const h=panel.querySelector('.panel-title');h.ondragstart=e=>{dragPanel=h.dataset.dragPanel;e.dataTransfer.setData('application/playform-panel',dragPanel);studio.classList.add('docking')};h.ondragend=()=>{dragPanel=null;studio.classList.remove('docking');$$('[data-slot]').forEach(d=>d.classList.remove('drop-target'))}}$$('[data-slot]').forEach(d=>{d.ondragover=e=>{if(dragPanel){e.preventDefault();d.classList.add('drop-target')}};d.ondragleave=()=>d.classList.remove('drop-target');d.ondrop=e=>{if(!dragPanel)return;e.preventDefault();const id=dragPanel;layout.panels[id]=d.dataset.slot;layout.order=layout.order.filter(x=>x!==id);layout.order.push(id);dragPanel=null;studio.classList.remove('docking');applyLayout()}});$$('[data-resize]').forEach(handle=>{const kind=handle.dataset.resize;handle.onpointerdown=e=>{if(matchMedia('(max-width:700px)').matches)return;e.preventDefault();handle.setPointerCapture(e.pointerId);const startX=e.clientX,startY=e.clientY,original=kind==='bottom'?layout.bottom:layout.widths[kind];handle.onpointermove=ev=>{if(kind==='bottom')layout.bottom=Math.max(120,Math.min(500,original+startY-ev.clientY));else layout.widths[kind]=Math.max(130,Math.min(420,original+(kind==='right'?-1:1)*(ev.clientX-startX)));applyLayout()};handle.onpointerup=()=>{handle.onpointermove=null;saveLayout()}};handle.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();if(kind==='bottom')layout.bottom=Math.max(120,Math.min(500,layout.bottom+(e.key==='ArrowUp'?20:-20)));else layout.widths[kind]=Math.max(130,Math.min(420,layout.widths[kind]+(e.key==='ArrowRight'?20:-20)));applyLayout()}})}
